/*
 Problem: 3987. Minimum Total Cost to Process All Elements
 Language: cpp
 Runtime: 7 ms (60.00%)
 Memory: 169.3 MB (63.88%)
 Tags: Array, Math, Simulation
*/
class Solution {
public:
    int minimumCost(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;

        long long cur = k;
        long long cnt = 0;

        for (const auto& x : nums) {
            if (cur < x) {
                long long t = (x - cur + k - 1) / k;
                cnt += t;
                cur += t * 1LL * k;
            }

            cur -= x;
        }

        return cnt % MOD * ((cnt + 1) % MOD) % MOD * ((MOD + 1) / 2) % MOD;
    }
};
